import "./orderlist.css";
import { useCart } from "./CartContext";
import { useNavigate } from "react-router-dom";

const OrderList = () => {
    const { orders, setOrders } = useCart(); // Get orders from context
    const navigate = useNavigate();

    // If no orders, show a message
    if (!orders || orders.length === 0) {
        return <p>Chưa có đơn hàng nào.</p>;
    }

    // Function to handle order placement
    const handlePlaceOrder = () => {
        // Display a success message
        alert("Đặt hàng thành công!");

        // Optionally, you could clear orders here if necessary
        setOrders([]); // Clear orders after placing them (optional)

        // Navigate back to the Cart page
        navigate("/cart");
    };

    return (
        <div className="order-list">
            <h2>📦 Đơn hàng đã đặt</h2>
            {orders.map((order) => (
                <div key={order.id} className="order-item">
                    <h3>🆔 Đơn hàng #{order.id}</h3>
                    <p>📅 Ngày đặt: {order.date}</p>
                    <p>💵 Tổng tiền: {order.total}k</p>

                    {/* Loop through items in the order */}
                    <div className="order-items">
                        {order.items.map((item, index) => (
                            <div key={index} className="order-item-details">
                                <img
                                    src={item.image}
                                    alt={item.name}
                                    className="order-item-image"
                                />
                                <div className="order-item-info">
                                    <span>{item.name}</span>
                                    <span>{item.price}k</span>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            ))}

            {/* Place Order Button */}
            <div className="place-order-btn-container">
                <button className="place-order-btn" onClick={handlePlaceOrder}>
                    Đặt hàng
                </button>
            </div>
        </div>
    );
};

export default OrderList;
